package dev.wowforever.importer.setup;
import static org.assertj.core.api.Assertions.*;
import dev.wowforever.importer.archive.SourceArchive;import dev.wowforever.importer.clientdata.CsvTable;import java.io.*;import java.sql.*;import java.util.*;import java.util.concurrent.CancellationException;import org.junit.jupiter.api.Test;
class NativeMapHierarchyAdapterTest {
 static final String MAPS="ID,ParentUiMapID,Name_lang,Type\n947,0,Azeroth,1\n1414,947,Kalimdor,2\n100,1414,Zone,3\n101,100,Battleground,6\n";
 static final String HEADER="ID,UiMapID,MapID,AreaID,Region_0,Region_1,Region_3,Region_4,UiMin_0,UiMin_1,UiMax_0,UiMax_1,WMODoodadPlacementID,WMOGroupID\n";
 static final String ROWS="1,947,1,0,0,0,100,100,0.1,0.2,0.5,0.8,0,0\n2,1414,1,0,0,0,100,100,0,0,1,1,0,0\n3,100,1,12,25,25,75,75,0,0,1,1,0,0\n4,101,30,13,0,0,100,100,0,0,1,1,0,0\n";
 NativeMapHierarchyProjection.Model model(String maps,String rows,Map<Long,Long> overrides)throws Exception{return NativeMapHierarchyProjection.build(CsvTable.read("maps",new StringReader(maps)),CsvTable.read("assignments",new StringReader(HEADER+rows)),overrides,Set.of(12L,13L),()->false);}
 @Test void recursiveNativeHierarchyIncludesDeepUnplacedDescendantsWithoutArtwork()throws Exception{var m=model(MAPS,ROWS,Map.of(12L,100L));assertThat(m.nodes()).extracting(NativeMapHierarchyProjection.Node::id).containsExactly(100L,101L,947L,1414L);assertThat(m.bounds()).containsKeys(1414L,100L).doesNotContainKey(101L);assertThat(m.zoneLinks()).extracting(NativeMapHierarchyProjection.ZoneLink::area).containsExactly(12L,13L);}
 @Test void continentBoundsComeFromNativeWorldUiRectangle()throws Exception{assertThat(model(MAPS,ROWS,Map.of()).bounds().get(1414L)).isEqualTo(new NativeMapHierarchyProjection.Bounds(0.1,0.2,0.5,0.8));}
 @Test void parentCyclesAreRejectedEvenWhenOutsideTheSelectedRoot(){assertThatThrownBy(()->model(MAPS+"200,201,CycleA,3\n201,200,CycleB,3\n",ROWS,Map.of())).hasMessageContaining("cycle");}
 @Test void duplicateMapAndAssignmentIdsAreRejected(){assertThatThrownBy(()->model(MAPS+"100,1414,Duplicate,3\n",ROWS,Map.of())).hasMessageContaining("duplicate native");assertThatThrownBy(()->model(MAPS,ROWS+"3,100,1,12,0,0,10,10,0,0,1,1,0,0\n",Map.of())).hasMessageContaining("Assignment ID");}
 @Test void unknownRootAndMissingColumnsFail(){assertThatThrownBy(()->model(MAPS.replace("947,0,Azeroth,1\n",""),ROWS,Map.of())).hasMessageContaining("root");assertThatThrownBy(()->model("ID,Name_lang\n947,Azeroth\n",ROWS,Map.of())).hasMessageContaining("column");}
 @Test void ambiguousAreaMappingsRemainUnlinked()throws Exception{var m=model(MAPS,ROWS+"5,101,30,12,0,0,100,100,0,0,1,1,0,0\n",Map.of());assertThat(m.ambiguousAreas()).containsExactly(12L);assertThat(m.zoneLinks()).noneMatch(l->l.area()==12);}
 @Test void repeatedIdenticalAreaMappingsAreProvenWithBothAssignmentIds()throws Exception{var m=model(MAPS,ROWS+"5,100,1,12,25,25,75,75,0,0,1,1,0,0\n",Map.of());assertThat(m.zoneLinks().stream().filter(l->l.area()==12).findFirst().orElseThrow().assignments()).containsExactly(3L,5L);}
 @Test void differingValidBoundsRemainNullRatherThanChoosingAnOrder()throws Exception{var m=model(MAPS,ROWS+"5,100,1,12,20,20,70,70,0,0,1,1,0,0\n",Map.of());assertThat(m.bounds()).doesNotContainKey(100L);assertThat(m.ambiguousBounds()).contains(100L);assertThat(m.zoneLinks()).anyMatch(l->l.area()==12);}
 @Test void explicitQuestieSuppressionAndConflictsNeverBecomeNativeLinks()throws Exception{var m=model(MAPS,ROWS,Map.of(12L,0L,13L,999L));assertThat(m.zoneLinks()).isEmpty();assertThat(m.conflictingOverrides()).containsExactlyInAnyOrder(12L,13L);}
 @Test void nativeAreaLinkDoesNotDependOnUsableGeometryOrAnImage()throws Exception{var m=model(MAPS,ROWS.replace("3,100,1,12,25,25,75,75","3,100,1,12,0,0,0,0"),Map.of(12L,100L));assertThat(m.bounds()).doesNotContainKey(100L);assertThat(m.zoneLinks()).anyMatch(l->l.area()==12&&l.map()==100);}
 @Test void wmoAssignmentsCannotEstablishUnqualifiedExteriorLinks()throws Exception{var m=model(MAPS,ROWS.replace("3,100,1,12,25,25,75,75,0,0,1,1,0,0","3,100,1,12,25,25,75,75,0,0,1,1,99,0"),Map.of());assertThat(m.zoneLinks()).noneMatch(l->l.area()==12);}
 @Test void sourceContextRejectsEraOlderBuildAndFalseAttAttribution()throws Exception{String pin="a".repeat(40);var q=new SourceArchive.Snapshot("questiedb",pin+" (local input; content identified by hash)","forever","","");NativeMapHierarchyAdapter.verifyContext(new SourceArchive.Snapshot("blizzard-client","1.60.1.70450","wow_classic_beta","1.60.1.70450","enUS"),q,pin);for(var n:List.of(new SourceArchive.Snapshot("blizzard-client","","wow_classic_era","1.60.1.70450","enUS"),new SourceArchive.Snapshot("blizzard-client","","wow_classic_beta","1.60.1.70374","enUS"),new SourceArchive.Snapshot("allthethings-world-map","","wow_classic_beta","1.60.1.70450","enUS")))assertThatThrownBy(()->NativeMapHierarchyAdapter.verifyContext(n,q,pin)).hasMessageContaining("context");assertThatThrownBy(()->NativeMapHierarchyAdapter.verifyContext(new SourceArchive.Snapshot("blizzard-client","","wow_classic_beta","1.60.1.70450","enUS"),q,"b".repeat(40))).hasMessageContaining("source pin");}
 @Test void cancellationDoesNotReturnPartiallyProjectedFacts(){assertThatThrownBy(()->NativeMapHierarchyProjection.build(CsvTable.read("maps",new StringReader(MAPS)),CsvTable.read("assignments",new StringReader(HEADER+ROWS)),Map.of(),Set.of(12L),()->true)).isInstanceOf(CancellationException.class);}
 @Test void appProjectionKeepsCoreIdentityAndAllowsNullBoundsWithoutArtwork()throws Exception{try(var c=connection()){var m=model(MAPS,ROWS,Map.of());var core=core();c.setAutoCommit(false);NativeMapHierarchyAdapter.project(c,m,"s",core);c.commit();NativeMapHierarchyAdapter.verify(c,m,"s",core);try(var s=c.createStatement();var r=s.executeQuery("SELECT ui_map_id FROM zone WHERE id=12")){assertThat(r.next()).isTrue();assertThat(r.getLong(1)).isEqualTo(100);}try(var s=c.createStatement();var r=s.executeQuery("SELECT x0 FROM ui_map_child WHERE child_ui_map_id=101")){assertThat(r.next()).isTrue();assertThat(r.getObject(1)).isNull();}}}
 @Test void conflictingExistingZoneMappingRollsBackInsteadOfReplacingIt()throws Exception{try(var c=connection()){try(var s=c.createStatement()){s.executeUpdate("UPDATE zone SET ui_map_id=999 WHERE id=12");}c.setAutoCommit(false);assertThatThrownBy(()->NativeMapHierarchyAdapter.project(c,model(MAPS,ROWS,Map.of()),"s",core())).hasMessageContaining("disagrees");c.rollback();try(var s=c.createStatement();var r=s.executeQuery("SELECT ui_map_id FROM zone WHERE id=12")){assertThat(r.next()).isTrue();assertThat(r.getLong(1)).isEqualTo(999);}try(var s=c.createStatement();var r=s.executeQuery("SELECT count(*) FROM sqlite_master WHERE name='ui_map'")){assertThat(r.next()).isTrue();assertThat(r.getInt(1)).isZero();}}}
 @Test void immutableCapturedInputsReplayEquivalentAppFacts()throws Exception {
  try(var archive=DriverManager.getConnection("jdbc:sqlite::memory:");var first=connection();var replay=connection()) {
   SourceArchive.initialize(archive);archive.setAutoCommit(false);String snapshot=SourceArchive.capture(archive,new SourceArchive.Snapshot("blizzard-client","fixture","wow_classic_beta","1.60.1.70450","enUS"),List.of(new SourceArchive.Artifact("csv/UiMap.csv","",MAPS.getBytes(java.nio.charset.StandardCharsets.UTF_8)),new SourceArchive.Artifact("csv/UiMapAssignment.csv","",(HEADER+ROWS).getBytes(java.nio.charset.StandardCharsets.UTF_8))));
   var artifacts=SourceArchive.artifacts(archive,snapshot);Map<String,String> bytes=new HashMap<>();for(var artifact:artifacts)bytes.put(artifact.path(),new String(artifact.bytes(),java.nio.charset.StandardCharsets.UTF_8));
   var original=model(MAPS,ROWS,Map.of());var rebuilt=NativeMapHierarchyProjection.build(CsvTable.read("maps",new StringReader(bytes.get("csv/UiMap.csv"))),CsvTable.read("assignments",new StringReader(bytes.get("csv/UiMapAssignment.csv"))),Map.of(),Set.of(12L,13L),()->false);
   assertThat(rebuilt).isEqualTo(original);NativeMapHierarchyAdapter.project(first,original,"s",core());NativeMapHierarchyAdapter.project(replay,rebuilt,"s",core());
   for(String query:List.of("SELECT * FROM ui_map ORDER BY id","SELECT * FROM ui_map_child ORDER BY child_ui_map_id","SELECT * FROM native_map_zone_link ORDER BY area_id","SELECT * FROM zone ORDER BY id"))assertThat(rows(replay,query)).isEqualTo(rows(first,query));
  }
 }
 private List<List<Object>> rows(Connection c,String query)throws SQLException {List<List<Object>> rows=new ArrayList<>();try(var s=c.createStatement();var r=s.executeQuery(query)){while(r.next()){List<Object> row=new ArrayList<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)row.add(r.getObject(i));rows.add(row);}}return rows;}
 private LibraryCandidateValidator.Validated core(){return new LibraryCandidateValidator.Validated("b".repeat(64),new SetupPlan.NativeIdentity("wow_classic_beta","1.60.1.70450","enUS"),"a".repeat(64),Map.of(),List.of());}
 private Connection connection()throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite::memory:");try(var s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");s.execute("CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT)");s.execute("INSERT INTO meta VALUES('source_ingestion_id','"+"a".repeat(64)+"'),('build_id','"+"b".repeat(64)+"')");s.execute("CREATE TABLE source_archive_snapshot(id TEXT PRIMARY KEY)");s.execute("INSERT INTO source_archive_snapshot VALUES('s')");s.execute("CREATE TABLE zone(id INTEGER PRIMARY KEY,ui_map_id INTEGER)");s.execute("INSERT INTO zone VALUES(12,NULL),(13,NULL)");}return c;}
}
